From 684e50a0512f98a075da7951a696d29eccb850b3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:04:48 +0100
Subject: [PATCH] applets/notifications: show critical notifications on all
 screens

Popups only appeared on the screen of the notification applet, so with
a projector or a second monitor a low battery warning was easy to miss.
Critical notifications now also get a copy on every other screen.

BUG: 471114
---
 applets/notifications/NotificationPopup.qml  |   2 +-
 applets/notifications/global/Globals.qml     | 128 +++++++++++++++++--
 applets/notifications/notificationapplet.cpp |  22 ++++
 applets/notifications/notificationapplet.h   |   3 +
 4 files changed, 142 insertions(+), 13 deletions(-)

diff --git a/applets/notifications/NotificationPopup.qml b/applets/notifications/NotificationPopup.qml
index bfc68dfe8b..387121be68 100644
--- a/applets/notifications/NotificationPopup.qml
+++ b/applets/notifications/NotificationPopup.qml
@@ -127,7 +127,7 @@ NotificationsApplet.NotificationWindow {
             rightPadding: 0
             hoverEnabled: true
             draggable: notificationItem.modelInterface.notificationType != NotificationManager.Notifications.JobType
-            onDismissRequested: NotificationsApplet.Globals.popupNotificationsModel.close(NotificationsApplet.Globals.popupNotificationsModel.index(notificationItem.modelInterface.index, 0))
+            onDismissRequested: notificationItem.modelInterface.closeClicked()

             TapHandler {
                 id: tapHandler
diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..862d3ddd04 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -155,6 +155,18 @@ QtObject {
     }
     onScreenRectChanged: repositionTimer.start()

+    // Available geometry of every screen other than the one the popups are placed on,
+    // critical notifications are shown there too so they aren't missed
+    readonly property var otherScreenRects: {
+        if (!plasmoid || screenRect.width <= 0 || screenRect.height <= 0) {
+            return [];
+        }
+        const centerX = screenRect.x + screenRect.width / 2;
+        const centerY = screenRect.y + screenRect.height / 2;
+        return plasmoid.availableScreenRects.filter(rect => rect.width > 0 && rect.height > 0
+            && !(centerX >= rect.x && centerX < rect.x + rect.width && centerY >= rect.y && centerY < rect.y + rect.height));
+    }
+
     readonly property Item visualParent: {
         if (!plasmoidItem) {
             return null;
@@ -376,18 +388,7 @@ QtObject {
                 continue;
             }

-
-            const leftMostX = screenRect.x + popupEdgeDistance;
-            const rightMostX = screenRect.x + screenRect.width - popupEdgeDistance - popup.width;
-
-            // If available screen rect is narrower than the popup, center it in the available rect
-            if (screenRect.width < popup.width || effectivePopupLocation & Qt.AlignHCenter) {
-                popup.x = screenRect.x + (screenRect.width - popup.width) / 2
-            } else if (effectivePopupLocation & Qt.AlignLeft) {
-                popup.x = leftMostX;
-            } else if (effectivePopupLocation & Qt.AlignRight) {
-                popup.x = rightMostX;
-            }
+            popup.x = popupX(screenRect, popup.width, effectivePopupLocation);

             if (effectivePopupLocation & Qt.AlignTop) {
                 // We want to calculate the new position based on its original target position to avoid positioning it and then
@@ -424,6 +425,42 @@ QtObject {

             popup.visible = visible;
         }
+
+        // Stack the copies of critical notifications on the other screens the same way
+        for (let s = 0; s < otherScreenRects.length; ++s) {
+            const rect = otherScreenRects[s];
+            let mirrorY = (effectivePopupLocation & Qt.AlignBottom) ? rect.y + rect.height - popupEdgeDistance : rect.y + popupEdgeDistance;
+
+            for (let i = 0; i < popupInstantiator.count; ++i) {
+                const popup = popupInstantiator.objectAt(i);
+                const mirror = popup ? popup.mirrors.objectAt(s) : null;
+                if (!mirror) {
+                    continue;
+                }
+
+                mirror.x = popupX(rect, mirror.width, effectivePopupLocation);
+                if (effectivePopupLocation & Qt.AlignTop) {
+                    mirror.y = mirrorY;
+                    mirrorY += mirror.height + (mirror.height > 0 ? popupSpacing : 0);
+                } else {
+                    mirrorY -= mirror.height;
+                    mirror.y = mirrorY;
+                    if (mirror.height > 0) {
+                        mirrorY -= popupSpacing;
+                    }
+                }
+            }
+        }
+    }
+
+    function popupX(rect, width, location) {
+        // If available screen rect is narrower than the popup, center it in the available rect
+        if (rect.width < width || location & Qt.AlignHCenter) {
+            return rect.x + (rect.width - width) / 2;
+        } else if (location & Qt.AlignLeft) {
+            return rect.x + popupEdgeDistance;
+        }
+        return rect.x + rect.width - popupEdgeDistance - width;
     }

     property NotificationManager.Notifications popupNotificationsModel: NotificationManager.Notifications {
@@ -680,6 +717,73 @@ QtObject {
             // popup width is fixed
             onHeightChanged: globals.positionPopups()

+            readonly property Instantiator mirrors: Instantiator {
+                model: popup.urgency === NotificationManager.Notifications.CriticalUrgency ? globals.otherScreenRects : []
+                delegate: NotificationPopup {
+                    popupWidth: popup.popupWidth
+                    showPopupTimeout: popup.showPopupTimeout
+                    isCritical: true
+
+                    modelTimeout: popup.modelTimeout
+                    defaultTimeout: popup.defaultTimeout
+                    dismissTimeout: popup.dismissTimeout
+
+                    modelInterface {
+                        index: popup.modelInterface.index
+                        notificationType: popup.modelInterface.notificationType
+                        applicationName: popup.modelInterface.applicationName
+                        applicationIconSource: popup.modelInterface.applicationIconSource
+                        originName: popup.modelInterface.originName
+                        time: popup.modelInterface.time
+                        configurable: popup.modelInterface.configurable
+                        dismissable: popup.modelInterface.dismissable
+                        closable: popup.modelInterface.closable
+                        summary: popup.modelInterface.summary
+                        body: popup.modelInterface.body
+                        accessibleDescription: popup.modelInterface.accessibleDescription
+                        icon: popup.modelInterface.icon
+                        hasDefaultAction: popup.modelInterface.hasDefaultAction
+                        urls: popup.modelInterface.urls
+                        urgency: popup.modelInterface.urgency
+                        jobState: popup.modelInterface.jobState
+                        percentage: popup.modelInterface.percentage
+                        jobError: popup.modelInterface.jobError
+                        suspendable: popup.modelInterface.suspendable
+                        killable: popup.modelInterface.killable
+                        jobDetails: popup.modelInterface.jobDetails
+                        configureActionLabel: popup.modelInterface.configureActionLabel
+                        actionNames: popup.modelInterface.actionNames
+                        actionLabels: popup.modelInterface.actionLabels
+                        hasReplyAction: popup.modelInterface.hasReplyAction
+                        replyActionLabel: popup.modelInterface.replyActionLabel
+                        replyPlaceholderText: popup.modelInterface.replyPlaceholderText
+                        replySubmitButtonText: popup.modelInterface.replySubmitButtonText
+                        replySubmitButtonIconName: popup.modelInterface.replySubmitButtonIconName
+
+                        onCloseClicked: popup.modelInterface.closeClicked()
+                        onDismissClicked: popup.modelInterface.dismissClicked()
+                        onConfigureClicked: popup.modelInterface.configureClicked()
+                        onDefaultActionInvoked: popup.modelInterface.defaultActionInvoked()
+                        onActionInvoked: actionName => popup.modelInterface.actionInvoked(actionName)
+                        onReplied: text => popup.modelInterface.replied(text)
+                        onOpenUrl: url => popup.modelInterface.openUrl(url)
+                        onFileActionInvoked: action => popup.modelInterface.fileActionInvoked(action)
+                        onSuspendJobClicked: popup.modelInterface.suspendJobClicked()
+                        onResumeJobClicked: popup.modelInterface.resumeJobClicked()
+                        onKillJobClicked: popup.modelInterface.killJobClicked()
+                    }
+
+                    onHoverEntered: popup.hoverEntered()
+                    onExpired: popup.expired()
+                    onHeightChanged: globals.positionPopups()
+                }
+                onObjectAdded: (index, object) => {
+                    globals.positionPopups();
+                    object.visible = true;
+                }
+                onObjectRemoved: globals.repositionTimer.start()
+            }
+
             Component.onCompleted: {
                 if (globals.inhibited) {
                     model.wasAddedDuringInhibition = false; // Don't count already shown notifications
diff --git a/applets/notifications/notificationapplet.cpp b/applets/notifications/notificationapplet.cpp
index 579dd0d790..8209abc961 100644
--- a/applets/notifications/notificationapplet.cpp
+++ b/applets/notifications/notificationapplet.cpp
@@ -13,6 +13,7 @@
 #include <QScreen>

 #include <Plasma/Containment>
+#include <Plasma/Corona>
 #include <PlasmaQuick/AppletQuickItem>
 #include <PlasmaQuick/Dialog>
 #include <PlasmaQuick/PlasmaWindow>
@@ -37,6 +38,12 @@ NotificationApplet::~NotificationApplet() = default;

 void NotificationApplet::init()
 {
+    if (auto *c = containment(); c && c->corona()) {
+        Plasma::Corona *corona = c->corona();
+        connect(corona, &Plasma::Corona::availableScreenRectChanged, this, &NotificationApplet::availableScreenRectsChanged);
+        connect(corona, &Plasma::Corona::screenAdded, this, &NotificationApplet::availableScreenRectsChanged);
+        connect(corona, &Plasma::Corona::screenRemoved, this, &NotificationApplet::availableScreenRectsChanged);
+    }
 }

 void NotificationApplet::configChanged()
@@ -80,6 +87,21 @@ QQuickItem *NotificationApplet::systemTrayRepresentation() const
     return PlasmaQuick::AppletQuickItem::itemForApplet(c);
 }

+QList<QRect> NotificationApplet::availableScreenRects() const
+{
+    QList<QRect> rects;
+    auto *c = containment();
+    if (!c || !c->corona()) {
+        return rects;
+    }
+
+    const Plasma::Corona *corona = c->corona();
+    for (uint i = 0; i < corona->numScreens(); ++i) {
+        rects.append(corona->availableScreenRect(i));
+    }
+    return rects;
+}
+
 bool NotificationApplet::isPrimaryScreen(const QRect &rect) const
 {
     QScreen *screen = QGuiApplication::primaryScreen();
